def solve():
    n = int(input())
    stack = []               # 模拟通道，列表尾部为顶端
    next_pop = 1
    sort_count = 0

    for _ in range(2 * n):
        parts = input().split()
        if parts[0] == 'push':
            val = int(parts[1])
            stack.append(val)    # 放入物品
        else:                    # pop
            if stack[-1] == next_pop:
                stack.pop()
                next_pop += 1
            else:
                sort_count += 1
                # 整理：从小到大排序，然后逆序使顶部为最小编号
                stack.sort(reverse=True)
                stack.pop()      # 弹出当前最小编号的物品
                next_pop += 1

    print(sort_count)

if __name__ == '__main__':
    solve()
```

